log = logging.getLogger("shopbot")

_DEFAULT_LOCALE = "en"
STRINGS = {
    "en": {
        "buy.ok": "Bought {item} for {price} gold. Balance: {balance}.",
        "buy.poor": "Not enough gold — {item} costs {price}, you have {balance}.",
    },
    "id": {
        "buy.ok": "Membeli {item} seharga {price} gold. Saldo: {balance}.",
        "buy.poor": "Gold tidak cukup — {item} harganya {price}, kamu punya {balance}.",
    },
}


def _t(key, locale, **kwargs) -> str:
    loc = getattr(locale, "value", locale) or _DEFAULT_LOCALE
    template = (STRINGS.get(loc) or STRINGS.get(str(loc).split("-")[0])
                or STRINGS.get(_DEFAULT_LOCALE, {})).get(key)
    if template is None:
        return key
    return template.format(**{k: to_str(v) for k, v in kwargs.items()})

class BuyAgainView(discord.ui.View):
    def __init__(self, author_id: int | None = None) -> None:
        super().__init__(timeout=60)
        self._author_id = author_id
        self.message = None

    @discord.ui.button(label="Buy again", style=discord.ButtonStyle.primary, custom_id="buy-again")
    async def _on_button(self, interaction: discord.Interaction, button: discord.ui.Button) -> None:
        if self._author_id is not None and interaction.user.id != self._author_id:
            await interaction.response.send_message("This button is not for you.", ephemeral=True)
            return
        await interaction.response.send_message(f"Use /buy again, {interaction.user.mention}!")

    async def on_timeout(self) -> None:
        for child in self.children:
            child.disabled = True
        if self.message is not None:
            await self.message.edit(content="Offer expired.")




class Bot(commands.Bot):
    def __init__(self) -> None:
        intents = discord.Intents.default()
        intents.guilds = True
        intents.members = True
        super().__init__(command_prefix="!", intents=intents)
        self.economy_db = None

    async def setup_hook(self) -> None:
        await self._economy_connect()
        _every_1h.start()
        await self.tree.sync()
        log.info("Commands synced globally.")

    async def on_ready(self) -> None:
        log.info(f"{self.user} is online")

    async def on_member_join(self, member: discord.Member) -> None:
        channel = member.guild.system_channel
        if channel is not None:
            await channel.send(f"Welcome to {member.guild.name}, {member.mention}!")

    async def _economy_connect(self) -> None:
        self.economy_db = await aiosqlite.connect("economy.db")
        await self.economy_db.execute("CREATE TABLE IF NOT EXISTS balances (user TEXT PRIMARY KEY, balance INTEGER)")
        await self.economy_db.execute("CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, user TEXT NOT NULL, amount INTEGER NOT NULL, key TEXT UNIQUE, created_at INTEGER NOT NULL)")
        await self.economy_db.commit()

    async def economy_balance(self, user_id: str) -> int:
        async with self.economy_db.execute("SELECT balance FROM balances WHERE user = ?", (user_id,)) as cursor:
            row = await cursor.fetchone()
        return row[0] if row is not None else 0

    async def _economy_apply(self, user_id: str, amount: int, key: str | None) -> None:
        # Idempotent on key: a duplicate key is a replay,
        # not an error (P11) — the balance + ledger land
        # in one transaction.
        if key is not None:
            async with self.economy_db.execute("SELECT 1 FROM ledger WHERE key = ?", (key,)) as cursor:
                if await cursor.fetchone() is not None:
                    return
        await self.economy_db.execute("INSERT INTO balances (user, balance) VALUES (?, ?) ON CONFLICT(user) DO UPDATE SET balance = balance + excluded.balance", (user_id, amount))
        await self.economy_db.execute("INSERT INTO ledger (user, amount, key, created_at) VALUES (?, ?, ?, ?)", (user_id, amount, key, int(time.time())))
        await self.economy_db.commit()

    async def economy_credit(self, user_id: str, amount: int, key: str | None = None) -> None:
        await self._economy_apply(user_id, amount, key)

    async def economy_debit(self, user_id: str, amount: int, key: str | None = None) -> bool:
        if await self.economy_balance(user_id) < amount:
            return False
        await self._economy_apply(user_id, -amount, key)
        return True

    async def economy_transfer(self, from_id: str, to_id: str, amount: int, key: str | None = None) -> bool:
        if await self.economy_balance(from_id) < amount:
            return False
        # The two legs get derived keys (the ledger's key
        # is UNIQUE, so one key cannot cover both legs).
        if key is not None:
            async with self.economy_db.execute("SELECT 1 FROM ledger WHERE key = ? OR key = ?", (f"{key}:out", f"{key}:in")) as cursor:
                if await cursor.fetchone() is not None:
                    return True
        await self._economy_apply(from_id, -amount, f"{key}:out" if key is not None else None)
        await self._economy_apply(to_id, amount, f"{key}:in" if key is not None else None)
        return True

    async def economy_get(self, table: str, key) -> types.SimpleNamespace | None:
        async with self.economy_db.execute(f"SELECT * FROM {table} WHERE user = ?", (key,)) as cursor:
            row = await cursor.fetchone()
            if row is None:
                return None
            cols = [d[0] for d in cursor.description]
            return types.SimpleNamespace(**dict(zip(cols, row)))

    async def economy_set(self, table: str, row) -> None:
        data = vars(row)
        cols = ", ".join(data)
        placeholders = ", ".join("?" * len(data))
        updates = ", ".join(f"{c} = excluded.{c}" for c in data)
        await self.economy_db.execute(f"INSERT INTO {table} ({cols}) VALUES ({placeholders}) ON CONFLICT(user) DO UPDATE SET {updates}", tuple(data.values()))
        await self.economy_db.commit()

    async def economy_delete(self, table: str, key) -> None:
        await self.economy_db.execute(f"DELETE FROM {table} WHERE user = ?", (key,))
        await self.economy_db.commit()


bot = Bot()


@bot.tree.command(name="ping", description="Answer with pong")
async def cmd_ping(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"Pong! Hello {interaction.user.mention}")


@bot.tree.command(name="buy", description="Buy an item from the shop")
@app_commands.describe(item="item", amount="amount")
@app_commands.choices(item=[app_commands.Choice(name="brick", value="brick"), app_commands.Choice(name="potion", value="potion")])
async def cmd_buy(interaction: discord.Interaction, item: str, amount: app_commands.Range[int, 1, 99] = 1) -> None:
    price = mul(shop_items.price_of(item), amount)
    bal = await bot.economy_balance(str(interaction.user.id))
    if bal < price:
        await interaction.response.send_message(_t("buy.poor", interaction.locale, price=price, balance=bal, item=item), ephemeral=True)
    else:
        await bot.economy_credit(str(interaction.user.id), neg(price), key=f"buy-{interaction.user.id}-{item}-{amount}")
        buy_again_view = BuyAgainView(interaction.user.id)
        await interaction.response.send_message(_t("buy.ok", interaction.locale, item=item, price=price, balance=sub(bal, price)), view=buy_again_view)
        buy_again_view.message = await interaction.original_response()


@bot.tree.command(name="balance", description="Show your balance")
async def cmd_balance(interaction: discord.Interaction) -> None:
    await interaction.response.send_message(f"Balance: {await bot.economy_balance(str(interaction.user.id))} gold.")


@tasks.loop(hours=1.0)
async def _every_1h() -> None:
    log.info("Hourly shop check ran")


@_every_1h.before_loop
async def _every_1h_wait_until_ready() -> None:
    await bot.wait_until_ready()


@bot.tree.error
async def on_app_command_error(interaction: discord.Interaction,
                               error: app_commands.AppCommandError) -> None:
    log.warning("Command failed: %s", error)
    message = "Sorry, that command hit a problem. Try again."
    try:
        if interaction.response.is_done():
            await interaction.followup.send(message, ephemeral=True)
        else:
            await interaction.response.send_message(message, ephemeral=True)
    except discord.HTTPException:
        log.warning("Could not answer the failed command.")


def _channel_text(channel) -> str:
    """The channel as text: its mention, its name, or ""."""
    if channel is None:
        return ""
    return getattr(channel, "mention", None) or str(channel)


def main() -> None:
    token = os.environ.get("DISCORD_TOKEN")
    if not token:
        raise SystemExit("set the DISCORD_TOKEN environment variable")
    bot.run(token)


if __name__ == "__main__":
    main()
